using System;using System.IO;using System.Reflection;
class RuntimeLogTest{static int Main(string[] args){try{var a=Assembly.LoadFrom(Path.Combine(args[0],"GPUPCMonitor.exe"));var config=a.GetType("Gpm.Config");var dir=Path.Combine(args[0],".tmp","runtime-log-test");Directory.CreateDirectory(dir);config.GetField("Dir").SetValue(null,dir);config.GetField("DataDir").SetValue(null,dir);var program=a.GetType("Gpm.Program");var flags=BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public;Exception sample;try{throw new InvalidOperationException("diagnostic test");}catch(Exception ex){sample=ex;}program.GetMethod("LogException",flags).Invoke(null,new object[]{"test",sample});var path=Path.Combine(dir,"runtime.log");if(!File.ReadAllText(path).Contains("InvalidOperationException"))throw new Exception("Exception details missing");Console.WriteLine("PASS exception type and stack recorded");File.WriteAllText(path,new string('x',2097153));program.GetMethod("RuntimeLog",flags).Invoke(null,new object[]{"rotation test"});if(!File.Exists(path+".1")||!File.ReadAllText(path).Contains("rotation test"))throw new Exception("Rotation failed");Console.WriteLine("PASS bounded log rotation");return 0;}catch(Exception e){Console.WriteLine(e.Message);return 1;}}}